#!/usr/bin/env -S npx tsx
import { runScenario, type Scenario } from "./claimOffice.js";

async function readStdin(): Promise<string> {
  const chunks: Buffer[] = [];
  for await (const chunk of process.stdin) {
    chunks.push(chunk as Buffer);
  }
  return Buffer.concat(chunks).toString("utf8");
}

function reportRejection(error: unknown): void {
  process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
  process.exitCode = 1;
}

try {
  const scenario = JSON.parse(await readStdin()) as Scenario;
  process.stdout.write(`${JSON.stringify(runScenario(scenario))}\n`);
} catch (error) {
  reportRejection(error);
}
import { payoutCapFor, payoutFor, payoutWithinRemainingCap, type Damage } from "./claimSettlement.js";
import type { InsuredItem } from "./itemCatalogue.js";
import { premiumFor, type Customer } from "./premium.js";

export type { Customer, Damage, InsuredItem };

export interface QuoteStep {
  op: "quote";
  items: InsuredItem[];
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: { cause: string; damages: Damage[] };
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteResult {
  premium: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export type StepResult = QuoteResult | ClaimResult;

interface Policy {
  items: InsuredItem[];
  remainingCap: number;
}

function openPolicy(items: InsuredItem[]): Policy {
  return { items, remainingCap: payoutCapFor(items) };
}

function settleClaim(step: ClaimStep, policy: Policy): ClaimResult {
  const payout = payoutWithinRemainingCap(payoutFor(step.incident.damages, policy.items), policy.remainingCap);
  policy.remainingCap -= payout;
  return { payout, remainingCap: policy.remainingCap };
}

export function runScenario(scenario: Scenario): { results: StepResult[] } {
  const policies = new Map<number, Policy>();
  const results = scenario.steps.map((step, index): StepResult => {
    if (step.op === "claim") {
      return settleClaim(step, policies.get(step.policy) as Policy);
    }
    policies.set(index, openPolicy(step.items));
    return { premium: premiumFor(step.items, scenario.customer, index) };
  });
  return { results };
}
import { isComponent, priceListEntryFor, type InsuredItem } from "./itemCatalogue.js";

export interface Customer {
  yearsWithMHPCO: number;
}

const PROCESSING_FEE = 5;
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const CURSE_SURCHARGE_PERCENT = 50;
const LONG_STANDING_CUSTOMER_YEARS = 2;
const LOYALTY_DISCOUNT_PERCENT = 20;
const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = 15;
const HIGH_ENCHANTMENT_LEVEL = 5;
const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
const WHOLE_PERCENT = 100;

// Amounts are kept in hundredths of a G so percentages stay exact until final rounding.
const HUNDREDTHS_PER_G = 100;

function toHundredths(amountInG: number): number {
  return amountInG * HUNDREDTHS_PER_G;
}

function percentOf(amountInHundredths: number, percent: number): number {
  return (amountInHundredths * percent) / WHOLE_PERCENT;
}

function roundInMhpcoFavour(amountInHundredths: number): number {
  return Math.ceil(amountInHundredths / HUNDREDTHS_PER_G);
}

function basePremiumOfOneItem(type: string): number {
  return priceListEntryFor(type).basePremium;
}

function basePremiumOfAlikeItems(type: string, count: number): number {
  if (isComponent(type) && count === BLOCK_SIZE) {
    return BLOCK_BASE_PREMIUM;
  }
  return count * basePremiumOfOneItem(type);
}

// Items are alike when they share the same type.
function countAlikeItems(items: InsuredItem[]): Map<string, number> {
  const countsByType = new Map<string, number>();
  for (const item of items) {
    countsByType.set(item.type, (countsByType.get(item.type) ?? 0) + 1);
  }
  return countsByType;
}

function policyBasePremium(items: InsuredItem[]): number {
  let total = 0;
  for (const [type, count] of countAlikeItems(items)) {
    total += basePremiumOfAlikeItems(type, count);
  }
  return total;
}

// Item-specific modifiers apply to the affected item's own base premium.
function percentOfItemBasePremium(item: InsuredItem, percent: number): number {
  return percentOf(toHundredths(basePremiumOfOneItem(item.type)), percent);
}

function curseSurcharge(item: InsuredItem): number {
  return item.cursed ? percentOfItemBasePremium(item, CURSE_SURCHARGE_PERCENT) : 0;
}

function highEnchantmentSurcharge(item: InsuredItem): number {
  const isHighlyEnchanted = (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
  return isHighlyEnchanted ? percentOfItemBasePremium(item, HIGH_ENCHANTMENT_SURCHARGE_PERCENT) : 0;
}

function itemSurcharges(items: InsuredItem[]): number {
  return items.reduce((sum, item) => sum + curseSurcharge(item) + highEnchantmentSurcharge(item), 0);
}

// Policy-wide modifiers apply to the policy base premium.
function firstInsuranceSurcharge(policyBaseInHundredths: number): number {
  return percentOf(policyBaseInHundredths, FIRST_INSURANCE_SURCHARGE_PERCENT);
}

function loyaltyDiscount(policyBaseInHundredths: number, customer: Customer): number {
  const isLongStandingCustomer = customer.yearsWithMHPCO >= LONG_STANDING_CUSTOMER_YEARS;
  return isLongStandingCustomer ? percentOf(policyBaseInHundredths, LOYALTY_DISCOUNT_PERCENT) : 0;
}

function followUpContractDiscount(policyBaseInHundredths: number, previousContracts: number): number {
  return previousContracts > 0 ? percentOf(policyBaseInHundredths, FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT) : 0;
}

function policyWideModifiers(policyBaseInHundredths: number, customer: Customer, previousContracts: number): number {
  return (
    firstInsuranceSurcharge(policyBaseInHundredths) -
    loyaltyDiscount(policyBaseInHundredths, customer) -
    followUpContractDiscount(policyBaseInHundredths, previousContracts)
  );
}

// All modifiers are additive on their base; the processing fee comes last.
export function premiumFor(items: InsuredItem[], customer: Customer, previousContracts: number): number {
  const policyBaseInHundredths = toHundredths(policyBasePremium(items));
  const premiumInHundredths =
    policyBaseInHundredths +
    policyWideModifiers(policyBaseInHundredths, customer, previousContracts) +
    itemSurcharges(items) +
    toHundredths(PROCESSING_FEE);
  return roundInMhpcoFavour(premiumInHundredths);
}
import { priceListEntryFor, type InsuredItem } from "./itemCatalogue.js";

export interface Damage {
  itemType: string;
  amount: number;
}

const CAP_MULTIPLIER = 2;
const DEDUCTIBLE = 100;
const HIGH_ENCHANTMENT_CLAUSE_LEVEL = 8;
const HIGH_ENCHANTMENT_REIMBURSEMENT_SHARE = 0.5;

function insuranceSum(items: InsuredItem[]): number {
  return items.reduce((sum, item) => sum + priceListEntryFor(item.type).insuranceValue, 0);
}

// The total payout per policy is capped at twice the insurance sum.
export function payoutCapFor(items: InsuredItem[]): number {
  return CAP_MULTIPLIER * insuranceSum(items);
}

// A claim pays out no more than what is left of the policy's cap.
export function payoutWithinRemainingCap(payout: number, remainingCap: number): number {
  return Math.min(payout, remainingCap);
}

function reimbursableAmount(damage: Damage, item: InsuredItem): number {
  const highEnchantmentClauseApplies = (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAUSE_LEVEL;
  if (highEnchantmentClauseApplies) {
    return damage.amount * HIGH_ENCHANTMENT_REIMBURSEMENT_SHARE;
  }
  return damage.amount;
}

// A damage entry paired with the insured item it claims.
interface CoveredDamage {
  damage: Damage;
  item: InsuredItem;
}

// A damage report is only valid when every damage amount is non-negative.
function assertValidDamageReport(damages: Damage[]): void {
  const invalid = damages.find((damage) => damage.amount < 0);
  if (invalid) {
    throw new Error(`Damage amount must not be negative: ${invalid.amount}`);
  }
}

function claimInsuredItem(damage: Damage, undamagedItems: InsuredItem[]): InsuredItem {
  const index = undamagedItems.findIndex((insured) => insured.type === damage.itemType);
  if (index === -1) {
    throw new Error(`Damaged item is not covered by the policy: ${damage.itemType}`);
  }
  const [item] = undamagedItems.splice(index, 1);
  return item;
}

// Each damage entry claims its own insured item; an item cannot be damaged twice in one incident.
function coveredDamages(damages: Damage[], insuredItems: InsuredItem[]): CoveredDamage[] {
  const undamagedItems = [...insuredItems];
  return damages.map((damage) => ({ damage, item: claimInsuredItem(damage, undamagedItems) }));
}

// For payouts, the MHPCO's favour means rounding down to whole G.
function roundInMhpcoFavour(amount: number): number {
  return Math.floor(amount);
}

// The deductible applies once per damage event.
function damageEventPayout({ damage, item }: CoveredDamage): number {
  return reimbursableAmount(damage, item) - DEDUCTIBLE;
}

// Intermediate amounts stay fractional; only the final payout is rounded.
export function payoutFor(damages: Damage[], insuredItems: InsuredItem[]): number {
  assertValidDamageReport(damages);
  const payout = coveredDamages(damages, insuredItems).reduce((sum, covered) => sum + damageEventPayout(covered), 0);
  return roundInMhpcoFavour(payout);
}
export interface InsuredItem {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

// One line of the MHPCO price list, in whole G.
export interface PriceListEntry {
  insuranceValue: number;
  basePremium: number;
}

// Components are the small items (runes, moonstones) priced and insured per piece.
const COMPONENT_TYPES = ["rune", "moonstone"];
const COMPONENT_PRICE: PriceListEntry = { insuranceValue: 250, basePremium: 25 };
const MAIN_ITEM_PRICES: Record<string, PriceListEntry> = {
  sword: { insuranceValue: 1000, basePremium: 100 },
  amulet: { insuranceValue: 600, basePremium: 60 },
  staff: { insuranceValue: 800, basePremium: 80 },
  potion: { insuranceValue: 400, basePremium: 40 },
};

export function isComponent(type: string): boolean {
  return COMPONENT_TYPES.includes(type);
}

export function priceListEntryFor(type: string): PriceListEntry {
  if (isComponent(type)) {
    return COMPONENT_PRICE;
  }
  if (!(type in MAIN_ITEM_PRICES)) {
    throw new Error(`Unknown item type: ${type}`);
  }
  return MAIN_ITEM_PRICES[type];
}

import { spawnSync } from "node:child_process";
import { describe, expect, it } from "vitest";

const runCli = (input: unknown) =>
  spawnSync("node_modules/.bin/tsx", ["src/cli.ts"], { input: JSON.stringify(input), encoding: "utf8" });

const schemaExample = {
  customer: { yearsWithMHPCO: 5 },
  steps: [
    { op: "quote", items: [{ type: "amulet", material: "silver", enchantment: 2, cursed: false }] },
    { op: "claim", policy: 0, incident: { cause: "fire", damages: [{ itemType: "amulet", amount: 200 }] } },
  ],
};

describe("claim-office CLI", () => {
  it("schema example on stdin → exit 0 and stdout {results:[{premium:59},{payout:100,remainingCap:1100}]}", () => {
    const result = runCli(schemaExample);
    expect(result.status).toBe(0);
    expect(JSON.parse(result.stdout)).toEqual({ results: [{ premium: 59 }, { payout: 100, remainingCap: 1100 }] });
  });
  it("quote with unknown item type → non-zero exit, error on stderr, nothing on stdout", () => {
    const result = runCli({ customer: { yearsWithMHPCO: 0 }, steps: [{ op: "quote", items: [{ type: "broomstick" }] }] });
    expect(result.status).not.toBe(0);
    expect(result.stderr).toContain("broomstick");
    expect(result.stdout).toBe("");
  });
  it("claim with negative damage amount → non-zero exit, error on stderr, nothing on stdout", () => {
    const result = runCli({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        { op: "quote", items: [{ type: "sword" }] },
        { op: "claim", policy: 0, incident: { cause: "fire", damages: [{ itemType: "sword", amount: -200 }] } },
      ],
    });
    expect(result.status).not.toBe(0);
    expect(result.stderr).not.toBe("");
    expect(result.stdout).toBe("");
  });
});
import { describe, expect, it } from "vitest";
import { runScenario, type Step } from "./claimOffice.js";

type Item = { type: string; material?: string; enchantment?: number; cursed?: boolean };

const alikeItems = (type: string, count: number): Item[] => Array.from({ length: count }, () => ({ type }));
const runes = (count: number): Item[] => alikeItems("rune", count);
const moonstones = (count: number): Item[] => alikeItems("moonstone", count);

const resultsFor = (steps: Step[], yearsWithMHPCO = 0) =>
  runScenario({ customer: { yearsWithMHPCO }, steps }).results;

const quoteStep = (items: Item[]): Step => ({ op: "quote", items });

type Damage = { itemType: string; amount: number };

const claimStep = (policy: number, damages: Damage[], cause = "dragon attack"): Step => ({
  op: "claim",
  policy,
  incident: { cause, damages },
});

const claimAgainst = (items: Item[], damages: Damage[]) => resultsFor([quoteStep(items), claimStep(0, damages)])[1];

const payoutFor = (item: Item, amount: number) =>
  (claimAgainst([item], [{ itemType: item.type, amount }]) as { payout: number }).payout;

const quoteFor = (items: Item[], yearsWithMHPCO = 0): number => {
  const [result] = resultsFor([quoteStep(items)], yearsWithMHPCO);
  return (result as { premium: number }).premium;
};

// Reading adopted for failures: the domain throws an Error; the CLI turns it into
// a non-zero exit status with an error description on stderr and nothing on stdout.
// Premiums below include the 10 % first-insurance surcharge (each quoted item is a
// first insurance) and the 5 G fee; "base" values from the spec are noted alongside.

describe("quote — base premiums (newcomer, first contract)", () => {
  it("empty item list → premium 5 G (only the processing fee)", () => {
    expect(quoteFor([])).toBe(5);
  });
  it("plain sword → 115 G (base 100 + 10 first insurance + 5 fee)", () => {
    expect(quoteFor([{ type: "sword" }])).toBe(115);
  });
  it("plain amulet → 71 G (base 60 + 6 + 5)", () => {
    expect(quoteFor([{ type: "amulet" }])).toBe(71);
  });
  it("plain staff → 93 G (base 80 + 8 + 5)", () => {
    expect(quoteFor([{ type: "staff" }])).toBe(93);
  });
  it("plain potion → 49 G (base 40 + 4 + 5)", () => {
    expect(quoteFor([{ type: "potion" }])).toBe(49);
  });
  it("1 rune → 33 G (base 25 + 2.5 + 5 = 32.5, rounded up)", () => {
    expect(quoteFor([{ type: "rune" }])).toBe(33);
  });
  it("1 moonstone → 33 G (base 25, same as rune)", () => {
    expect(quoteFor([{ type: "moonstone" }])).toBe(33);
  });
  it("2 runes → 60 G (base 50)", () => {
    expect(quoteFor(runes(2))).toBe(60);
  });
  it("3 runes → 71 G (base 60, block applies)", () => {
    expect(quoteFor(runes(3))).toBe(71);
  });
  it("4 runes → 115 G (base 100, no block — block requires exactly 3)", () => {
    expect(quoteFor(runes(4))).toBe(115);
  });
  it("7 runes → 198 G (base 175; 197.5 rounded up in MHPCO's favor)", () => {
    expect(quoteFor(runes(7))).toBe(198);
  });
  it("2 runes + 1 moonstone → 88 G (base 75, no block: different types; 87.5 rounded up)", () => {
    expect(quoteFor([...runes(2), ...moonstones(1)])).toBe(88);
  });
  it("3 runes + 3 moonstones → 137 G (base 120, two separate blocks)", () => {
    expect(quoteFor([...runes(3), ...moonstones(3)])).toBe(137);
  });
  it("unknown item type (broomstick) → throws an Error", () => {
    expect(() => quoteFor([{ type: "broomstick" }])).toThrow(Error);
  });
});

describe("quote — item-specific modifiers", () => {
  it("cursed sword, enchantment 3, newcomer → 165 G (100 + 50 curse + 10 first + 5)", () => {
    expect(quoteFor([{ type: "sword", material: "steel", enchantment: 3, cursed: true }])).toBe(165);
  });
  it("sword with exactly enchantment 5 → 145 G (100 + 30 high enchantment + 10 + 5)", () => {
    expect(quoteFor([{ type: "sword", enchantment: 5 }])).toBe(145);
  });
  it("cursed sword with exactly enchantment 5 → 195 G (both surcharges)", () => {
    expect(quoteFor([{ type: "sword", enchantment: 5, cursed: true }])).toBe(195);
  });
  it("sword with enchantment 4 → 115 G (no high-enchantment surcharge)", () => {
    expect(quoteFor([{ type: "sword", enchantment: 4 }])).toBe(115);
  });
  it("cursed sword with enchantment 4 → 165 G (curse surcharge only)", () => {
    expect(quoteFor([{ type: "sword", enchantment: 4, cursed: true }])).toBe(165);
  });
  it("cursed potion → 69 G (40 + 20 curse + 4 + 5) — surcharges apply to non-sword items", () => {
    expect(quoteFor([{ type: "potion", cursed: true }])).toBe(69);
  });
  it("amulet with enchantment 6 → 89 G (60 + 18 high enchantment + 6 + 5)", () => {
    expect(quoteFor([{ type: "amulet", enchantment: 6 }])).toBe(89);
  });
  it("cursed sword + plain amulet → 231 G (base 160 + 50 curse on sword only + 16 first + 5)", () => {
    expect(quoteFor([{ type: "sword", cursed: true }, { type: "amulet" }])).toBe(231);
  });
});

describe("quote — policy-wide modifiers", () => {
  it("customer with exactly 2 years, plain sword → 95 G (100 − 20 loyalty + 10 + 5)", () => {
    expect(quoteFor([{ type: "sword" }], 2)).toBe(95);
  });
  it("customer with 1 year, plain sword → 115 G (no loyalty discount)", () => {
    expect(quoteFor([{ type: "sword" }], 1)).toBe(115);
  });
  it("second quote of a 0-year customer, plain sword → 100 G (100 + 10 − 15 follow-up + 5)", () => {
    const sword = [{ type: "sword" }];
    expect(resultsFor([quoteStep(sword), quoteStep(sword)])).toEqual([{ premium: 115 }, { premium: 100 }]);
  });
  it("third quote of a 0-year customer, plain sword → 100 G (15 % on each follow-up contract)", () => {
    const sword = [{ type: "sword" }];
    expect(resultsFor([quoteStep(sword), quoteStep(sword), quoteStep(sword)])).toEqual([
      { premium: 115 },
      { premium: 100 },
      { premium: 100 },
    ]);
  });
  it("3-year customer, second quote, cursed sword enchantment 7 → 160 G (integration example)", () => {
    const results = resultsFor(
      [quoteStep([{ type: "amulet" }]), quoteStep([{ type: "sword", material: "steel", enchantment: 7, cursed: true }])],
      3,
    );
    expect(results).toEqual([{ premium: 59 }, { premium: 160 }]);
  });
});

describe("claim — reimbursement", () => {
  it("schema example: 5-year customer, silver amulet ench 2 → premium 59 G; fire damage 200 → payout 100, remainingCap 1100", () => {
    const results = resultsFor(
      [
        quoteStep([{ type: "amulet", material: "silver", enchantment: 2, cursed: false }]),
        claimStep(0, [{ itemType: "amulet", amount: 200 }], "fire"),
      ],
      5,
    );
    expect(results).toEqual([{ premium: 59 }, { payout: 100, remainingCap: 1100 }]);
  });
  it("steel sword ench 3, damage 500 → payout 400, remainingCap 1600", () => {
    expect(
      claimAgainst([{ type: "sword", material: "steel", enchantment: 3 }], [{ itemType: "sword", amount: 500 }]),
    ).toEqual({ payout: 400, remainingCap: 1600 });
  });
  it("rune, damage 200 → payout 100, remainingCap 400", () => {
    expect(claimAgainst(runes(1), [{ itemType: "rune", amount: 200 }])).toEqual({ payout: 100, remainingCap: 400 });
  });
  it("moonstone, damage 200 → payout 100, remainingCap 400", () => {
    expect(claimAgainst(moonstones(1), [{ itemType: "moonstone", amount: 200 }])).toEqual({
      payout: 100,
      remainingCap: 400,
    });
  });
  it("staff, damage 300 → payout 200, remainingCap 1400", () => {
    expect(claimAgainst([{ type: "staff" }], [{ itemType: "staff", amount: 300 }])).toEqual({
      payout: 200,
      remainingCap: 1400,
    });
  });
  it("potion, damage 300 → payout 200, remainingCap 600", () => {
    expect(claimAgainst([{ type: "potion" }], [{ itemType: "potion", amount: 300 }])).toEqual({
      payout: 200,
      remainingCap: 600,
    });
  });
  it("steel sword ench 9, damage 1000 → payout 400 (50 % then deductible)", () => {
    expect(payoutFor({ type: "sword", material: "steel", enchantment: 9 }, 1000)).toBe(400);
  });
  it("dragon sword ench 9, damage 1000 → payout 400 (50 % rule wins)", () => {
    expect(payoutFor({ type: "sword", material: "dragon", enchantment: 9 }, 1000)).toBe(400);
  });
  it("dragon sword exactly ench 8, damage 1000 → payout 400", () => {
    expect(payoutFor({ type: "sword", material: "dragon", enchantment: 8 }, 1000)).toBe(400);
  });
  it("dragon sword ench 5, damage 800 → payout 700 (full reimbursement minus deductible)", () => {
    expect(payoutFor({ type: "sword", material: "dragon", enchantment: 5 }, 800)).toBe(700);
  });
  it("steel sword ench 8, damage 901 → payout 350 (350.5 rounded down)", () => {
    expect(payoutFor({ type: "sword", material: "steel", enchantment: 8 }, 901)).toBe(350);
  });
  it("sword 500 + amulet 300 in one incident → payout 600 (deductible per damaged item), remainingCap 2600", () => {
    expect(
      claimAgainst(
        [{ type: "sword" }, { type: "amulet" }],
        [
          { itemType: "sword", amount: 500 },
          { itemType: "amulet", amount: 300 },
        ],
      ),
    ).toEqual({ payout: 600, remainingCap: 2600 });
  });
  it("two swords insured, both damaged 500 → payout 800, remainingCap 3200 (cap 4000)", () => {
    expect(
      claimAgainst(
        [{ type: "sword" }, { type: "sword" }],
        [
          { itemType: "sword", amount: 500 },
          { itemType: "sword", amount: 500 },
        ],
      ),
    ).toEqual({ payout: 800, remainingCap: 3200 });
  });
});

describe("claim — cap", () => {
  it("cursed sword policy, damage 500 → remainingCap 1600 (cap 2000 from insurance value, not premium)", () => {
    expect(claimAgainst([{ type: "sword", cursed: true }], [{ itemType: "sword", amount: 500 }])).toEqual({
      payout: 400,
      remainingCap: 1600,
    });
  });
  it("sword + 3 runes policy, sword damage 500 → remainingCap 3100 (insurance sum 1750)", () => {
    expect(claimAgainst([{ type: "sword" }, ...runes(3)], [{ itemType: "sword", amount: 500 }])).toEqual({
      payout: 400,
      remainingCap: 3100,
    });
  });
  it("sword policy, two successive claims of 1500 → payouts 1400 then 600; remainingCap 600 then 0", () => {
    const damages = [{ itemType: "sword", amount: 1500 }];
    expect(resultsFor([quoteStep([{ type: "sword" }]), claimStep(0, damages), claimStep(0, damages)]).slice(1)).toEqual([
      { payout: 1400, remainingCap: 600 },
      { payout: 600, remainingCap: 0 },
    ]);
  });
});

describe("claim — rejections", () => {
  it("damage to an amulet when only a sword is insured → throws an Error", () => {
    expect(() => claimAgainst([{ type: "sword" }], [{ itemType: "amulet", amount: 200 }])).toThrow(Error);
  });
  it("damage to an unknown item type → throws an Error", () => {
    expect(() => claimAgainst([{ type: "sword" }], [{ itemType: "broomstick", amount: 200 }])).toThrow(Error);
  });
  it("two sword damages but only one sword insured → throws an Error", () => {
    expect(() =>
      claimAgainst(
        [{ type: "sword" }],
        [
          { itemType: "sword", amount: 500 },
          { itemType: "sword", amount: 500 },
        ],
      ),
